const BPM = 129
const DELAY_MIX = 0.375
const REVERB = 0.12
setcpm(BPM / 4)
await samples({ sd_petikan: { d3: guitarSample() } })
const riffD = note("d3 f#3 g3 a3 d3 f#3 g3 a3")
const riffB = note("b2 d3 e3 f#3 b2 d3 e3 f#3")
function guitarSample() {
  return 'data:audio/wav;base64,'
}
cat(riffD, riffD, riffD, riffD, riffD, riffD,
    riffB, riffB, riffD, riffD, riffB, riffB)
  .s("sd_petikan")
  .velocity("1 0.96 0.97 0.96 0.99 0.96 0.97 0.96")
  .attack(0)
  .release(0.012)
  .delay(DELAY_MIX)
  .delaytime((60 / BPM) * 0.75)
  .delayfeedback(0.45)
  .room(REVERB)
  .rsize(3)
  .roomfade(1.8)
  .roomlp(6500)
  .roomdim(4200)
  .gain(1)
  .postgain(1)
  .orbit(0)
